ControlPropertyState.AutoRuleBindingString:
If(
    DropdownCanvas1.Selected.RunResult = 'RunResult (CH-Tbl-ValidationRuns)'.Fail,
    UpdateContext(
        {
            varOutgoingEmail: Concatenate(
                "<html>",
                "<body>",
                "<p>El pre-registro de los archivos fue rechazado por estos motivos: </p>",
                "<ul><li>",
                Concat(
                    Filter(
                        colValidatedResults,
                        ValidationResult = 'ValidationResult (CH-Tbl-ValidationResults)'.Fail
                    ),
                    ValidationRule.ValidationFailMessage,
                    "</li><li>"
                ),
                "</li></ul>",
                "<p>Numero de seguimiento: ",
                Table1_1.Selected.Name,
                "</p>",
                "</body>",
                "</html>"
            )
        }
    ),
    UpdateContext(
        {
            varOutgoingEmail: Concatenate(
                "<html>",
                "<body>",
                "<p>El pre-registro de los archivos fue aceptado. </p>",
                "<p>Numero de seguimiento: ",
                Table1_1.Selected.Name,
                "</p>",
                "</body>",
                "</html>"
            )
        }
    );
NewForm('form Declaration');
SubmitForm('form Declaration');


)

UpdateContext(
    {
        varFiltrosQueryCorreo: Concatenate(
            "$filter=",
            If(
                !IsBlank('dp FechaDesde'.SelectedDate),
                "receivedDateTime ge " & Text(
                    'dp FechaDesde'.SelectedDate,
                    "yyyy-mm-dd"
                ) & "T00:00:00Z"
                //,"receivedDateTime ge 2000-01-01T00:00:00Z"
            ),
             If(Or(
                    And(
                        !IsBlank(Trim(SearchInput1_1.Value)),
                        !IsBlank('dp FechaDesde'.SelectedDate)
                    ),And(
                        !IsBlank('dp FechaHasta'.SelectedDate),
                        !IsBlank('dp FechaDesde'.SelectedDate)
                    )
                )," AND "),
            If(
                !IsBlank('dp FechaHasta'.SelectedDate),
                "receivedDateTime le " & Text(
                    'dp FechaHasta'.SelectedDate,
                    "yyyy-mm-dd"
                ) & "T00:00:00Z"
            ),
            If(
                Or(
                    And(
                        !IsBlank(Trim(SearchInput1_1.Value)),
                        !IsBlank('dp FechaHasta'.SelectedDate)
                    )
                ),
                " AND "
            ), 
            If(
                !IsBlank(Trim(SearchInput1_1.Value)),
                //"from/emailAddress/address eq '" & Trim(TextInputCanvas1.Value)&"'"
                "contains(from/emailAddress/address,'" & Trim(SearchInput1_1.Value)&"')"
            )
        )
    }
);

Select(btn_ConstruirURI);
